const createdFunctions=new Map;export const createFunction=t=>{let n=createdFunctions.get(t);return n||(n=new Function(`return ${t}`)(),createdFunctions.set(t,n),n)};export function stringifyFunction(t){let n=t.toString();try{new Function(`(${n})`)}catch{let t="function ";n.startsWith("async ")&&(t=`async ${t}`,n=n.substring(6)),n=`${t}${n}`;try{new Function(`(${n})`)}catch{throw new Error("Passed function cannot be serialized!")}}return n}export const interpolateFunction=(t,n)=>{let e=stringifyFunction(t);for(const[t,c]of Object.entries(n))e=e.replace(new RegExp(`PLACEHOLDER\\(\\s*(?:'${t}'|"${t}")\\s*\\)`,"g"),`(${c})`);return createFunction(e)};